# Runtime Metrics Protocol-First Exposure

## Root Cause
Runtime metrics exist in `MetricsTracker` but are not exposed via the protocol to the client HUD. The `session.state` message lacks a metrics field, so the client cannot display runtime statistics.

## Smallest Safe Fix

### 1. Protocol: Add metrics to session.state payload
**File: `packages/protocol/src/messages.ts`**

```diff
@@ -108,6 +108,13 @@ export type ServerMessage =
     | {
         version: Version;
         type: "session.state";
         payload: {
           phase: SessionPhase;
           paused: boolean;
           preparedSeed: number | null;
           threadIds: { gameplayByAgentId: Record<string, string>; builder?: string };
           connected: boolean;
+          metrics: {
+            turnsTotal: number;
+            invalidOutputCount: number;
+            actionAppliedCount: number;
+            actionRejectedCount: number;
+            queuedActions: number;
+          };
           runtime: {
             model: string | null;
             effort: TurnEffort;
```

### 2. Runtime Server: Include metrics in session state
**File: `apps/game-runtime/src/runtime/GameRuntimeServer.ts`**

```diff
@@ -707,6 +707,7 @@ export class GameRuntimeServer {
       this.emitMessage({
         version: PROTOCOL_VERSION,
         type: "session.state",
         payload: {
           phase: this.phase,
           paused: this.paused,
           preparedSeed: this.preparedSeed,
           threadIds: this.threadIds,
           connected: this.connected,
+          metrics: this.metrics.snapshot(),
           runtime: {
             model: this.turnModel,
             effort: this.turnEffort,
```

### 3. Client: Display metrics in HUD
**File: `apps/game-client/src/App.tsx`**

```diff
@@ -93,6 +93,13 @@ export default function App() {
   const [runtimeModel, setRuntimeModel] = useState<string | null>(null);
   const [runtimeEffort, setRuntimeEffort] = useState<string>("low");
   const [runtimeSchedulerMs, setRuntimeSchedulerMs] = useState<number>(0);
   const [runtimeQueueAhead, setRuntimeQueueAhead] = useState<number>(0);
+  const [runtimeMetrics, setRuntimeMetrics] = useState<{
+    turnsTotal: number;
+    invalidOutputCount: number;
+    actionAppliedCount: number;
+    actionRejectedCount: number;
+    queuedActions: number;
+  }>({ turnsTotal: 0, invalidOutputCount: 0, actionAppliedCount: 0, actionRejectedCount: 0, queuedActions: 0 });
   const [collapsedHudSections, setCollapsedHudSections] = useState<Record<HudSectionKey, boolean>>({
